export const V3_TEMPLATE_VERSION = "3.0.0";
export type UpgradePlan = { projectDirectory: string; fromVersion: string; toVersion: string; actions: LifecycleAction[]; conflicts: string[]; mutations: FileMutation[]; nextManifest: ProjectManifest; nextState: ProjectState };
function readText(projectDirectory: string, path: string) { const absolute = resolveProjectPath(projectDirectory, path); if (!existsSync(absolute)) throw new Error(`Expected project file is missing: ${path}`); return { content: readFileSync(absolute, "utf8"), hash: hashFile(absolute) }; }
