function patchRoutes(content: string): string { if (content.includes("registerGeneratedRoutes")) return content; const anchor = /import \{ readinessRoutes \} from ["']\.\/readiness["'];/; if (!anchor.test(content)) throw new Error("Cannot safely upgrade src/routes/index.ts: readiness import anchor not found."); let next = content.replace(anchor, (match) => `${match}\nimport { registerGeneratedRoutes } from "./launchstack.generated";`); const closing = next.lastIndexOf("}\n"); if (closing < 0) throw new Error("Cannot safely upgrade src/routes/index.ts: function boundary not found."); return `${next.slice(0, closing)}\n  await registerGeneratedRoutes(app);\n${next.slice(closing)}`; }
