  const capabilitiesPath = "src/launchstack/capabilities/index.ts"; if (!existsSync(resolveProjectPath(projectDirectory, capabilitiesPath))) { mutations.push({ type: "write", path: capabilitiesPath, content: `import type { FastifyInstance } from "fastify";\nexport async function registerLaunchStackCapabilities(app: FastifyInstance): Promise<void> { void app; }\n`, owner: "launchstack:core", version: V3_TEMPLATE_VERSION, expectedSha256: null }); actions.push({ id: "v3:capability-registry", kind: "write", target: capabilitiesPath, detail: "create capability ownership boundary" }); }
  try { const routes = readText(projectDirectory, "src/routes/index.ts"); const next = patchRoutes(routes.content); if (next !== routes.content) { mutations.push({ type: "write", path: "src/routes/index.ts", content: next, owner: "launchstack:metadata", version: V3_TEMPLATE_VERSION, expectedSha256: routes.hash }); actions.push({ id: "v3:routes-wire", kind: "write", target: "src/routes/index.ts", detail: "wire generated route registry" }); } } catch (error) { conflicts.push(error instanceof Error ? error.message : String(error)); }
